package pl.zagranietyper.fixture;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import pl.zagranietyper.config.ApiFootballConfig;import pl.zagranietyper.model.ApiFootballFixturePlayersResponse;import java.time.Instant;import static org.junit.jupiter.api.Assertions.*;
class ApiFootballClientPlayersTest {@Test void preservesCanonicalValuesZerosNullsAndUnknownFields(){String json="""
{"errors":[],"response":[{"team":{"id":22,"name":"Away first"},"players":[{"player":{"id":7,"name":"Á. Test"},"statistics":[{"games":{"minutes":63,"position":"G","rating":"7.2","captain":false,"substitute":true},"offsides":0,"shots":{"total":0,"on":null},"goals":{"total":1,"assists":1,"saves":4},"passes":{"total":20,"key":2,"accuracy":"80%"},"tackles":{"total":3,"blocks":1,"interceptions":2},"duels":{"total":5,"won":4},"dribbles":{"attempts":2,"success":1,"past":0},"fouls":{"drawn":1,"committed":2},"cards":{"yellow":1,"red":0},"penalty":{"won":0},"future":{"x":9}}]}]}]}
""";var c=new ApiFootballClient(new ApiFootballConfig("x","http://localhost",1,1,0),new ObjectMapper());ApiFootballFixturePlayersResponse r=c.parseFixturePlayers(json,99,200,Instant.EPOCH);assertEquals(ApiFootballFixturePlayersResponse.Status.SUCCESS,r.status());var p=r.players().get(0);assertEquals(22,p.teamId());assertEquals(7,p.playerId());assertEquals(63,p.minutes());assertEquals(0,p.shotsTotal());assertNull(p.shotsOnTarget());assertEquals(1,p.goals());assertEquals(1,p.assists());assertEquals(4,p.saves());assertEquals(2,p.foulsCommitted());assertEquals(1,p.yellowCards());assertEquals(0,p.redCards());assertEquals(9,p.rawStatistics().path("future").path("x").asInt());}@Test void unknownOrEmptyResponseIsSafe(){var c=new ApiFootballClient(new ApiFootballConfig("x","http://localhost",1,1,0),new ObjectMapper());assertEquals(ApiFootballFixturePlayersResponse.Status.EMPTY,c.parseFixturePlayers("{\"errors\":[],\"response\":[]}",1,200,Instant.EPOCH).status());assertEquals(ApiFootballFixturePlayersResponse.Status.PARSE_ERROR,c.parseFixturePlayers("{}",1,200,Instant.EPOCH).status());}}
